
import React from 'react';
import { Link } from 'react-router-dom';

const Header: React.FC = () => {
  return (
    <header className="bg-timeline-navy text-white p-4 shadow-md">
      <div className="container mx-auto flex justify-between items-center">
        <Link to="/" className="text-2xl font-bold flex items-center">
          <span className="text-timeline-gold">Crono</span>
          <span>Guerra</span>
        </Link>
        <nav>
          <ul className="flex space-x-6">
            <li>
              <Link to="/" className="hover:text-timeline-gold transition-colors">
                Linha do Tempo
              </Link>
            </li>
            <li>
              <Link to="/sobre" className="hover:text-timeline-gold transition-colors">
                Sobre
              </Link>
            </li>
          </ul>
        </nav>
      </div>
    </header>
  );
};

export default Header;
